<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {vertices,anchors,row,relation,redEdges,root,seven} from './model.mjs'
import PascalNavigator from './PascalNavigator.vue'
import {patterns} from './patterns.mjs'
import {gradedSolid} from './cellulation.mjs'
import {createScene} from './scene.js'
const host=ref(null),a=ref(seven?1:3),b=ref(seven?2:12),pick=ref('A'),layer=ref('both'),all=ref(false),failed=ref(false),mapping=ref('');let scene
const support=v=>anchors.filter(n=>relation(v,n)==='R'),shared=computed(()=>support(a.value).filter(n=>support(b.value).includes(n))),fmt=s=>s.join(', ')||'none'
const shape=ref('cube'),gradeT=ref(2),gradeO=ref(2),grade=computed({get:()=>shape.value==='tetrahedron'?gradeT.value:gradeO.value,set:v=>{(shape.value==='tetrahedron'?gradeT:gradeO).value=v}}),solid=computed(()=>['cube','sheet'].includes(shape.value)?null:gradedSolid(shape.value,grade.value))
const select=n=>{(pick.value==='A'?a:b).value=n};const sync=()=>scene?.update(a.value,b.value,all.value,layer.value,shape.value==='sheet'?'cube':shape.value,grade.value);watch([a,b,all,layer,shape,grade],sync);onMounted(()=>{try{scene=createScene(host.value,select);sync()}catch{failed.value=true}});onUnmounted(()=>scene?.dispose())
const corners=Array.from({length:seven?4:8},(_,i)=>({i,x:36+92*(i&1)+42*(i>>2),y:70+74*((i>>1)&1)-40*(i>>2),bits:i.toString(2).padStart(seven?2:3,'0'),red:[1+(i&1),4+((i>>1)&1),7+(i>>2)]}));const edges=corners.flatMap(c=>(seven?[1,2]:[1,2,4]).filter(m=>!(c.i&m)).map(m=>[c,corners[c.i|m]]));const cornerWord=c=>Array.from({length:anchors.length},(_,i)=>c.red.includes(i+1)?'R':'B').join('');const word=ref(cornerWord(corners[0]));const red=computed(()=>[...word.value].flatMap((v,i)=>v==='R'?[i+1]:[]));const corner=computed({get:()=>corners.findIndex(c=>cornerWord(c)===word.value),set:i=>{if(i>=0)word.value=cornerWord(corners[i])}});const adjacent=computed(()=>patterns(anchors.length).filter(w=>{const moves=[...w].map((v,i)=>v!==word.value[i]?i:-1).filter(i=>i>=0);return moves.length===2&&moves[1]===moves[0]+1}))
const map=computed(()=>mapping.value.trim().split(/[\s,]+/).map(Number)),valid=computed(()=>map.value.length===anchors.length&&new Set(map.value).size===anchors.length&&map.value.every(n=>anchors.includes(n))),desired=computed(()=>valid.value?red.value.map(i=>map.value[i-1]):[]),hits=computed(()=>valid.value?vertices.filter(n=>!anchors.includes(n)&&support(n).length===3&&desired.value.every(s=>support(n).includes(s))):[])
</script>
<template><header><h2>Viewing (3,{{seven?7:8}}) · catalogue record 1</h2><label>Scene <select v-model="shape"><option value="cube">FCC graph witness</option><option value="tetrahedron">Graded tetrahedron</option><option value="octahedron">Graded octahedron</option><option value="sheet">Spreadsheet patterns</option></select></label><p v-if="shape==='cube'">{{vertices.length}} vertices · root {{root}} and its {{anchors.length-1}} red neighbors occupy {{anchors.length}} corners · {{vertices.length-anchors.length}} bulk vertices<span v-if="seven"> · one corner intentionally unoccupied</span>.</p></header><section v-show="shape!=='sheet'"><div v-if="shape==='cube'"><h2>Compare actual graph rows</h2><label>Row A <select v-model.number="a"><option v-for="n in vertices" :key="n">{{n}}</option></select></label><label>Row B <select v-model.number="b"><option v-for="n in vertices" :key="n">{{n}}</option></select></label><label>Path layer <select v-model="layer"><option value="both">Both</option><option>A</option><option>B</option></select></label><label><input type="checkbox" v-model="all"> Background: all {{redEdges.length}} red edges</label></div><fieldset v-if="solid"><legend>FCC subdivision · {{shape}}</legend><label v-if="solid">Grade {{grade}} <input aria-label="Solid grade" v-model.number="grade" type="range" min="1" :max="shape==='tetrahedron'?8:4"></label><p v-if="solid" aria-live="polite">{{solid.counts.tetrahedron}} elementary tetrahedra · {{solid.counts.octahedron}} elementary octahedra. Gold outline: {{grade}} FCC steps per edge. Teal lines: subdivision. Only the solid and its subdivision are drawn.</p></fieldset><button @click="scene?.reset()">Reset camera</button>
<p v-if="failed">WebGL unavailable. The comparison, swap cube and matrix remain interactive.</p><div v-show="!failed" ref="host" class="scene"></div><template v-if="shape==='cube'"><p aria-live="polite"><b style="color:#ff967f">A {{a}} → {{fmt(support(a))}}</b> · <b style="color:#73cbff">B {{b}} → {{fmt(support(b))}}</b> · <b style="color:#ffd264">Shared anchors: {{fmt(shared)}}</b></p><p>Diamond = root {{root}}. Shared anchors are graph data; shared FCC path segments are routing choices. Pick a label or matrix row to change <select aria-label="Active row" v-model="pick"><option>A</option><option>B</option></select>.</p></template></section>
<template v-if="shape==='sheet'"><PascalNavigator :width="anchors.length" :word="word" @pick="word=$event"/><section><h2>3 · Test a spreadsheet correspondence</h2><p>{{seven?'Width seven: positions 1↔2 and 4↔5 can swap independently with position 7 fixed red. This gives a square, not an eight-corner swap cube.':'Width eight: positions 1↔2, 4↔5 and 7↔8 swap independently to give a cube.'}} Each corner is a row configuration, not a graph vertex.</p>
<svg viewBox="0 0 220 175" width="220" :aria-label="seven?'Two-swap square':'Three-swap cube'"><line v-for="[u,v] in edges" :key="u.i+'-'+v.i" :x1="u.x" :y1="u.y" :x2="v.x" :y2="v.y" stroke="#86b2cd"/><g v-for="c in corners" :key="c.i" @click="corner=c.i" style="cursor:pointer"><rect :x="c.x-18" :y="c.y-11" width="36" height="22" rx="5" :fill="corner===c.i?'#ffd264':'#c0d3e0'"/><text :x="c.x" :y="c.y+5" text-anchor="middle">{{c.bits}}</text></g></svg>
<p><label>Swap corner <select v-model.number="corner"><option disabled :value="-1">Outside displayed swap family</option><option v-for="c in corners" :key="c.i" :value="c.i">{{c.bits}}</option></select></label><code>{{word}}</code> · Red positions: {{fmt(red)}}</p><p>Other patterns one legal adjacent swap away: <button v-for="w in adjacent" :key="w" @click="word=w">{{w}}</button></p>
<label>Graph anchor for each of the {{anchors.length}} table positions <input v-model="mapping" placeholder="Enter distinct anchor labels" size="32"></label><button @click="mapping=anchors.join(', ')">Try spreadsheet column order</button><button @click="mapping=''">Clear</button>
<p aria-live="polite" v-if="!mapping.trim()">No correspondence specified.</p><p v-else-if="!valid">Use each anchor exactly once: {{fmt(anchors)}}.</p><p v-else aria-live="polite">Proposed support: {{fmt(desired)}}. Exact outside-row matches: {{fmt(hits)}}. <button v-for="n in hits" :key="n" @click="select(n);shape='cube'">Inspect {{n}}</button></p><small>This tests equality of one red support under your column mapping, not joint graph feasibility.</small></section></template>
<table v-if="shape==='cube'"><caption>Exact rooted matrix · select a row to inspect</caption><thead><tr><th>Vertex</th><th v-for="n in anchors" :key="n">{{n}}</th></tr></thead><tbody><tr v-for="n in vertices" :key="n" :class="{chosen:n===a||n===b}"><th><button @click="select(n)">{{n}}</button></th><td v-for="(c,i) in row(n)" :key="i" :class="c">{{c}}</td></tr><tr><th>{{vertices.length+1}}</th><td :colspan="anchors.length">Blank spreadsheet padding — not a vertex</td></tr></tbody></table></template>
